import type { StaticImageData } from "next/image";
import { athensDesktop, athensMobile } from "./athens-ascii";
import desktopColors from "@/assets/ascii/athens-desktop.png";
import mobileColors from "@/assets/ascii/athens-mobile.png";

type Scene = { cols: number; rows: number; text: string };

/**
 * The footer background: Athens in colour ASCII — the Acropolis with the
 * Parthenon (its frieze in the blue and red it was painted), Lycabettus,
 * terracotta roofs and blue domes, cypresses, and formulas in the sky.
 * Generated by scripts/generate-athens-ascii.py.
 *
 * Each scene is a single block of real text. Its colours come from a tiny
 * PNG with one pixel per character, painted through the glyphs with
 * `background-clip: text` and scaled without smoothing, so every character
 * takes the exact colour of its cell. Sized in `ch`/`em` so the grid holds
 * in any monospace font, always covers the width and is anchored to the
 * bottom; taller footers simply reveal more sky.
 */
export function AsciiAthens() {
  return (
    <div aria-hidden="true" className="pointer-events-none absolute inset-0 -z-10 select-none overflow-hidden">
      <AsciiScene scene={athensDesktop} colors={desktopColors} className="ascii-scene--wide hidden lg:block" />
      <AsciiScene scene={athensMobile} colors={mobileColors} className="ascii-scene--tall lg:hidden" />
    </div>
  );
}

function AsciiScene({ scene, colors, className }: { scene: Scene; colors: StaticImageData; className: string }) {
  return (
    <div className={`ascii-scene ${className}`} style={{ width: `${scene.cols}ch`, height: `${scene.rows}em` }}>
      <pre className="ascii-layer" style={{ backgroundImage: `url(${colors.src})` }}>
        {scene.text}
      </pre>
    </div>
  );
}
